Contract ProcessSaleService::endSale(): Real {

            precondition:
          self.CurrentSale.oclIsUndefined() = false and self.CurrentSale.IsComplete = false and self.CurrentSale.IsReadytoPay = false

            postcondition:
          self.CurrentSale.IsReadytoPay = true and result = self.CurrentSale.Amount and if self.CurrentSale.ContainedSalesLine@pre->isEmpty() then self.CurrentSale.Amount = 0.0 else self.CurrentSale.Amount = self.CurrentSale.ContainedSalesLine@pre->sumBy(s:SalesLineItem|s.Subamount@pre) endif

        }
